//! The Rust normalizers against `CPython`'s `unicodedata` and `str.casefold`,
//! an independent implementation. Fixtures: `tests/fixtures/unicode`,
//! generated by `tools/build_unicode_fixtures.py`.

use std::collections::HashMap;
use std::path::PathBuf;

use univo_core::{normalize_hostname, normalize_text};

fn fixture(name: &str) -> String {
    let path = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("../../tests/fixtures/unicode")
        .join(name);
    std::fs::read_to_string(path).unwrap()
}

fn parse_code_points(hex: &str) -> String {
    hex.split(' ')
        .map(|code| char::from_u32(u32::from_str_radix(code, 16).unwrap()).unwrap())
        .collect()
}

fn text(input: &str, case_fold: bool) -> String {
    let mut out = String::new();
    normalize_text(input, case_fold, &mut out);
    out
}

#[test]
fn folded_text_matches_cpython_for_every_code_point() {
    let expected: HashMap<u32, String> = fixture("text_codepoints.tsv")
        .lines()
        .filter(|line| !line.starts_with('#'))
        .map(|line| {
            let (code, output) = line.split_once('\t').unwrap();
            (
                u32::from_str_radix(code, 16).unwrap(),
                parse_code_points(output),
            )
        })
        .collect();
    assert!(expected.len() > 2000);

    let mut mismatches = Vec::new();
    for character in (0..=0x10_FFFF).filter_map(char::from_u32) {
        let input = character.to_string();
        let wanted = expected.get(&u32::from(character)).unwrap_or(&input);
        if text(&input, true) != *wanted {
            mismatches.push(format!("U+{:04X}", u32::from(character)));
        }
    }
    assert!(
        mismatches.is_empty(),
        "{} mismatches: {mismatches:?}",
        mismatches.len()
    );
}

#[test]
fn strings_match_cpython_for_text_and_hostnames() {
    let mut checked = 0;
    for line in fixture("strings.jsonl").lines() {
        let case: serde_json::Value = serde_json::from_str(line).unwrap();
        let input = case["input"].as_str().unwrap();
        assert_eq!(
            text(input, true),
            case["text"].as_str().unwrap(),
            "{input:?}"
        );
        assert_eq!(
            text(input, false),
            case["text_no_fold"].as_str().unwrap(),
            "{input:?}"
        );
        let mut host = String::new();
        normalize_hostname(input, &mut host);
        assert_eq!(host, case["hostname"].as_str().unwrap(), "{input:?}");
        checked += 1;
    }
    assert!(checked >= 1000);
}
